UPDATE proofs SET body_tex = '\emph{Idea.} The numbers $A_k(z) = \frac{(-1)^k}{k!}\mathcal H_\psi^{(k)}(z)$ are the Taylor coefficients of $w \mapsto \mathcal H_\psi(z - w)$. If $z$ has a unique nearest pole, at distance $d$, they grow like $d^{-k}$. Two parallel lemmas compare this growth on the line $\Re z = \sigma$ with $(\sigma - \theta)^{-k}$:
\begin{itemize}
\item the hypothesis caps it, by the \hyperref[8JT2]{one-sided bound for the Taylor coefficients};
\item a pole with $\Re\rho > \theta$ would exceed the cap, by the \hyperref[8JT5]{lower bound for the Taylor coefficients}.
\end{itemize}
Both lemmas bound the same quantity $|A_k(\sigma + i\tau)| + \Re A_k(\sigma)$, one from above and one from below. The upper bound works for this combination because it is at most $2\int_0^\infty g_+ K_k$, with $g(u) = \mathcal G_\psi(e^u)$, which involves only the positive part of $\mathcal G_\psi$: the hypothesis bounds $\mathcal G_\psi$ only from above.

\emph{The contradiction.} Suppose that some $\rho \in Z$ has $\Re\rho > \theta$. The hypothesis of the proposition is that of \ref{8JT2}; let $\sigma_0$ be as there, fix a real $\sigma \ge \sigma_0$, and let $C$ and $K$ be as there. Since $\sigma > 1$, \ref{8JT5} gives $\tau$, $c$, $d < \sigma - \theta$ and $k_0$. For every $k \in K$ with $k \ge k_0$,
\[ c\, d^{-k} \le |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le C\, (\sigma - \theta)^{-k}, \]
so $\bigl((\sigma - \theta)/d\bigr)^{k} \le C/c$. Since $K$ is infinite and $(\sigma - \theta)/d > 1$, this fails for large $k \in K$. Hence $\Re\rho \le \theta$ for every $\rho \in Z$.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 01:45:00', updated_by = 'claude' WHERE id = 102;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '102', 10, 'parallel-lemmas-displays-2026-11-25', '{"result_id":113,"body_tex":"\\emph{Idea.} The numbers $A_k(z) = \\frac{(-1)^k}{k!}\\mathcal H_\\psi^{(k)}(z)$ are the Taylor coefficients of $w \\mapsto \\mathcal H_\\psi(z - w)$. If $z$ has a unique nearest pole, at distance $d$, they grow like $d^{-k}$. Two parallel lemmas compare this growth on the line $\\Re z = \\sigma$ with $(\\sigma - \\theta)^{-k}$:\n\\begin{itemize}\n\\item the hypothesis caps it, by the \\hyperref[8JT2]{one-sided bound for the Taylor coefficients};\n\\item a pole with $\\Re\\rho > \\theta$ would exceed the cap, by the \\hyperref[8JT5]{lower bound for the Taylor coefficients}.\n\\end{itemize}\nBoth lemmas bound the same quantity $|A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma)$, one from above and one from below. The upper bound works for this combination because it is at most $2\\int_0^\\infty g_+ K_k$, with $g(u) = \\mathcal G_\\psi(e^u)$, which involves only the positive part of $\\mathcal G_\\psi$: the hypothesis bounds $\\mathcal G_\\psi$ only from above.\n\n\\emph{The contradiction.} Suppose that some $\\rho \\in Z$ has $\\Re\\rho > \\theta$. The hypothesis of the proposition is that of \\ref{8JT2}; let $\\sigma_0$ be as there, fix a real $\\sigma \\ge \\sigma_0$, and let $C$ and $K$ be as there. Since $\\sigma > 1$, \\ref{8JT5} gives $\\tau$, $c$, $d < \\sigma - \\theta$ and $k_0$. For every $k \\in K$ with $k \\ge k_0$,\n\\[ c\\, d^{-k} \\le |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le C\\, (\\sigma - \\theta)^{-k}, \\]\nso $\\bigl((\\sigma - \\theta)/d\\bigr)^{k} \\le C/c$. Since $K$ is infinite and $(\\sigma - \\theta)/d > 1$, this fails for large $k \\in K$. Hence $\\Re\\rho \\le \\theta$ for every $\\rho \\in Z$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
INSERT INTO write_guard (ok) SELECT 0 WHERE NOT EXISTS (SELECT 1 FROM proofs WHERE id = 121 AND revision = 1);
UPDATE proofs SET body_tex = '\emph{Idea.} $A_k(z)$ is the $k$-th Taylor coefficient of $w \mapsto \mathcal H_\psi(z - w)$. If $z$ has a unique nearest pole, at distance $d$, then $|A_k(z)|$ grows like $d^{-k}$ (Step 1). A pole with $\Re\rho > \theta$ is closer than $\sigma - \theta$ to the line $\Re s = \sigma$; we find a point of that line where it shows up in $A_k$.

\emph{Step 1: Taylor coefficients near a pole.} Let $\Re z > 1$, and let $\overline B(z, r)$ be a closed disc in $\Re s > 0$ that contains exactly one pole $\rho$ of $\mathcal H_\psi$, with residue $c_\rho$. Then
\[ A_k(z) = \frac{c_\rho}{(z - \rho)^{k+1}} + O(r^{-k}) \qquad (k \to \infty). \]
Indeed, write $\mathcal H_\psi(s) = \frac{c_\rho}{s - \rho} + h(s)$ with $h$ holomorphic on a neighbourhood of $\overline B(z, r)$. Since $\frac{d^k}{ds^k}\frac{1}{s - \rho} = \frac{(-1)^k k!}{(s - \rho)^{k+1}}$, the first term contributes $\frac{c_\rho}{(z - \rho)^{k+1}}$ to $A_k(z)$, and Cauchy''s estimate gives $\frac{|h^{(k)}(z)|}{k!} \le r^{-k} \max_{|s - z| = r} |h(s)|$. In the same way $A_k(z) = O(r^{-k})$ if $\overline B(z, r)$ contains no pole.

\emph{Step 2: two distances.} Fix $\sigma > 1$, and put $D_* = \sigma - \theta$ and $D = \min_{\rho \in Z} |\sigma - \rho|$, the distance from $\sigma$ to the nearest pole; the minimum exists because $Z$ is nonempty and \hyperref[8JS5]{locally finite}. Every pole is \hyperref[8JN4]{simple with nonzero residue}, and every pole has $\Re\rho < 1 < \sigma$, since $L(s,\chi) \ne 0$ for $\Re s \ge 1$ \cite{Davenport}. By hypothesis some $\rho_0 \in Z$ has $\sigma - \Re\rho_0 < D_*$. All discs below are centred on the line $\Re s = \sigma$ and have radius less than $D_* < \sigma$, so they lie in $\Re s > 0$.

\emph{Case (a): some pole $\rho_1$ has $\sigma - \Re\rho_1 < \min(D, D_*)$.} Choose a closed interval $J$ around $\Im\rho_1$ such that $|\sigma + i\tau - \rho_1| < \min(D, D_*)$ for all $\tau \in J$. Only finitely many poles lie within distance $\min(D, D_*)$ of the compact segment $\{\sigma + i\tau \mid \tau \in J\}$. Two of them are equidistant from $\sigma + i\tau$ for at most one $\tau$: if their imaginary parts differ, equality of the squared distances is a linear equation in $\tau$ with nonzero slope; if their imaginary parts agree, their real parts differ, and since both lie left of the line their distances to it differ. Choose $\tau \in J$ avoiding these finitely many values and put $z = \sigma + i\tau$. Then $z$ has a unique nearest pole $\rho$, at distance $d \le |z - \rho_1| < \min(D, D_*)$. Choose $r$ with $d < r < \min(D, D_*)$ such that $\rho$ is the only pole in $\overline B(z, r)$. The disc $\overline B(\sigma, r)$ contains no pole, as $r < D$. By Step 1,
\begin{align*}
|A_k(z)| + \Re A_k(\sigma) &\ge |A_k(z)| - |A_k(\sigma)| \\
&\ge |c_\rho|\, d^{-k-1} - O(r^{-k}) \ge \frac{|c_\rho|}{2d}\, d^{-k}
\end{align*}
for all large $k$, because $d < r$. This is the claim with $c = |c_\rho|/(2d)$. We cannot simply take $z = \sigma$: there the conjugate poles $\rho_1$ and $\bar\rho_1$ are equally close, and their contributions to $A_k(\sigma)$ may cancel. See the \hyperref[8JT8]{picture of case (a)}.

\emph{Case (b): every pole has $\sigma - \Re\rho \ge \min(D, D_*)$.} For $\rho_0$ this gives $\min(D, D_*) \le \sigma - \Re\rho_0 < D_*$, so $D < D_*$. A pole $\rho$ nearest to $\sigma$ satisfies $D = |\sigma - \rho| \ge \sigma - \Re\rho \ge D$. So equality holds, $\rho$ is real, and $\rho = \beta = \sigma - D$; in particular $\beta$ is the only pole at distance $D$ from $\sigma$. Its residue $c_\beta$ is positive by the \hyperref[8JS7]{corollary on real poles}. Choose $r$ with $D < r < D_*$ such that $\beta$ is the only pole in $\overline B(\sigma, r)$. By Step 1, $A_k(\sigma) = c_\beta D^{-k-1} + O(r^{-k})$, so with $\tau = 0$
\begin{align*}
|A_k(\sigma)| + \Re A_k(\sigma) &\ge 2\Re A_k(\sigma) \\
&\ge 2c_\beta D^{-k-1} - O(r^{-k}) \ge \frac{c_\beta}{D}\, D^{-k}
\end{align*}
for all large $k$. This is the claim with $d = D$ and $c = c_\beta/D$. Here the sign of $c_\beta$ is essential: if $c_\beta$ were negative, $|A_k(\sigma)| + \Re A_k(\sigma)$ could be small. See the \hyperref[8JT9]{picture of case (b)}.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 01:45:00', updated_by = 'claude' WHERE id = 121;
